CREATE OR REPLACE FUNCTION public.network_workspace_access(_ws uuid,_manage boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=_ws AND m.user_id=auth.uid() AND m.removed_at IS NULL AND w.status='active' AND p.status='active' AND p.deleted_at IS NULL AND NOT m.is_contractor AND (m.role IN ('owner','admin') OR m.can_manage_trips OR (NOT _manage AND m.can_view_workspace_requests))) $$;
CREATE OR REPLACE FUNCTION public.network_assigned_access(_ws uuid,_driver uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.network_workspace_access(_ws,true) OR EXISTS(SELECT 1 FROM public.drivers d JOIN public.workspace_members m ON m.workspace_id=d.workspace_id AND m.user_id=d.user_id JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE d.id=_driver AND d.user_id=auth.uid() AND d.workspace_id=_ws AND m.removed_at IS NULL AND p.deleted_at IS NULL AND p.status='active' AND w.status='active') $$;
DO $$ DECLARE def text; old_clause text:='IF NOT FOUND THEN PERFORM set_config(''app.network_write'',previous_flag,true); RETURN jsonb_build_object(''ok'',false,''error'',''This offer is no longer available''); END IF;'; BEGIN SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='network_accept_offer'; IF position(old_clause in def)>0 THEN EXECUTE replace(def,old_clause,'IF NOT FOUND THEN RAISE EXCEPTION ''Source trip no longer available''; END IF;'); END IF; SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='network_list_offers'; IF position('''wave_id''' in def)=0 THEN EXECUTE replace(def,'''id'',o.id,','''id'',o.id,''wave_id'',o.wave_id,'); END IF; END $$;
REVOKE ALL ON FUNCTION public.network_accept_offer(uuid,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.network_accept_offer(uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_account_conversation_access(_thread uuid,_write boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.message_threads t JOIN public.user_profiles p ON p.user_id=auth.uid() WHERE t.id=_thread AND t.related_person_id IS NOT NULL AND p.status='active' AND p.deleted_at IS NULL AND ((t.related_person_id=auth.uid() AND EXISTS(SELECT 1 FROM public.thread_participants tp WHERE tp.thread_id=t.id AND tp.user_id=auth.uid())) OR (t.created_by=auth.uid() AND public.admin_can('people','read') AND public.admin_can('messaging',CASE WHEN _write THEN 'manage' ELSE 'read' END) AND (CASE WHEN t.related_workspace_id IS NULL THEN public.is_master_admin(auth.uid()) ELSE public.admin_can_account(t.related_workspace_id) END)))) $$;
REVOKE ALL ON FUNCTION public.admin_account_conversation_access(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.admin_account_conversation_access(uuid,boolean) TO authenticated;
CREATE POLICY account_conversations_read ON public.message_threads FOR SELECT TO authenticated USING(public.admin_account_conversation_access(id,false));
CREATE POLICY account_messages_read ON public.messages FOR SELECT TO authenticated USING(public.admin_account_conversation_access(thread_id,false));
CREATE POLICY account_messages_write ON public.messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND public.admin_account_conversation_access(thread_id,true));
COMMENT ON FUNCTION public.admin_account_conversation_access(uuid,boolean) IS 'In-app account conversation access is limited to its target person and currently scoped sender admin.';